written("w5_ice_floats", 5, 2, "5d",
        stem="Ice floats on water. State what this tells you about the density of ice compared with water, and explain in terms of mass and volume what happens when water freezes.",
        points=[P("ice is less dense than water", ["less dense", "lower density", "density is lower", "smaller density", "not as dense"]),
                P("when water freezes its mass stays the same but its volume increases (it expands), so the density decreases", ["mass stays the same", "same mass", "volume increases", "expands", "takes up more space", "bigger volume", "larger volume"])],
        pitfalls=[PF(["ice is denser", "ice is more dense", "ice has a higher density"], "Objects float only when they are LESS dense than the liquid. Ice floats, so it is less dense than water.")],
        model_answer="Ice floats, so it is less dense than water. When water freezes, its mass does not change but its volume increases (water expands as it freezes), so its density, mass ÷ volume, decreases.",
        hints=["What has to be true about an object's density for it to float on a liquid?",
               "Same mass, different volume: which way did the volume change when the water froze?",
               "State the density comparison and explain it with mass and volume."],
        keywords="ice less dense; same mass, larger volume",
        sample_pass=["Ice is less dense than water because when water freezes its volume increases while the mass stays the same", "ice has a lower density as it expands on freezing"],
        sample_fail=["Ice is denser than water", "Ice is lighter because it loses mass"])

# ---------------------------------------------------------------- L3
written("w5_snowshoes", 5, 3, "5b",
        stem="Explain why a person wearing wide snowshoes does not sink into soft snow, while the same person in ordinary boots does.",
        points=[P("the person's weight (force) is the same in both cases", ["same weight", "same force", "weight is the same", "force is the same", "weight does not change"]),
                P("snowshoes spread the weight over a much larger area", ["larger area", "bigger area", "greater area", "spread", "wider", "more area"]),
                P("pressure = force ÷ area, so the pressure on the snow is smaller and it is not compressed enough for the person to sink", ["smaller pressure", "lower pressure", "less pressure", "reduces the pressure", "pressure decreases", "force ÷ area", "force / area", "does not sink"])],
        min_points=2,
        model_answer="The person's weight is the same with or without snowshoes, but snowshoes spread that weight over a much larger area. Pressure = force ÷ area, so the pressure on the snow is much smaller and the snow is not compressed enough for the person to sink.",
        hints=["Same person, same weight. What is different about the contact with the snow?",
               "Larger area with the same force: what happens to the pressure?",
               "Explain the unchanged force, the larger area, and the effect on pressure."],
        keywords="same weight, larger area, smaller pressure",
        figure=lambda: sketches.pressure_block("weight", "large area of snowshoe"),
        sample_pass=["The weight is spread over a bigger area so the pressure on the snow is lower and the person does not sink", "same force but larger area gives a smaller pressure"],
        sample_fail=["Snowshoes are lighter than boots", "Snowshoes grip the snow"])

written("w5_drawing_pin", 5, 3, "5b",
        stem="A drawing pin has a flat, wide head and a sharp point. Explain how this design lets a small push of the thumb drive the pin into a board.",
        points=[P("the force of the thumb on the head is transmitted to the point: the same force acts at both ends", ["same force", "force is transmitted", "transmitted to the point", "equal force", "passed on to the point", "both ends"]),
                P("the head has a large area, so the pressure on the thumb is low and it does not hurt", ["large area", "wide head", "low pressure on the thumb", "does not hurt", "small pressure on the thumb", "comfortable", "spread over the thumb"]),
                P("the point has a tiny area, so the pressure on the board is very high and the pin goes in", ["tiny area", "small area", "sharp point", "high pressure", "large pressure", "great pressure", "goes into the board", "pierces"])],
        min_points=2,
        model_answer="The force of the thumb on the head is transmitted through the pin to the point, so the same force acts at both ends. The wide head has a large area, so the pressure on the thumb is small and it does not hurt. The sharp point has a tiny area, so the same force produces a very high pressure on the board and the pin pierces it.",
        hints=["Same force at both ends of the pin. What differs is the area at each end.",
               "Large area at the head, tiny area at the point: compare the two pressures.",
               "Explain the transmitted force and the pressure at each end."],
        keywords="same force both ends; large head → low pressure on thumb; sharp point → high pressure on board",
        sample_pass=["The same force acts at both ends; the wide head means low pressure on the thumb, while the sharp point means very high pressure on the board",
                     "the head spreads the force over a large area so it does not hurt, and the point concentrates it into a tiny area to pierce the board"],
        sample_fail=["The head is heavy so it pushes the pin in", "The point is made of harder metal"])

